  ($str$variable$str$, 'USA', $str$2026-TransferDie$str$, $str$minFormSurfaceToleranceRestrikeThreshold$str$, $str$.5$str$, $str$Length$str$, $str$Threshold used for determining when to RESTRIKE a Form GCD with respect to minimum surface tolerance of Form.$str$, $jsonb${"Variable Name":"minFormSurfaceToleranceRestrikeThreshold","String Value":0.5,"Unit Type Name":"Length","Notes":"Threshold used for determining when to RESTRIKE a Form GCD with respect to minimum surface tolerance of Form.","Applies To":"General / Shared"}$jsonb$::jsonb),
